from fractions import Fraction as Fr
from decimal import Decimal as Dc
SUBJ = {'ar': 'اللغة العربية', 'math': 'الرياضيات', 'sci': 'العلوم', 'en': 'اللغة الإنجليزية', 'life': 'المهارات الحياتية'}
COL = {'ar': ('#7c3aed', '#efe7ff'), 'math': ('#2563eb', '#e0ecff'), 'sci': ('#16a34a', '#dcf5e4'), 'en': ('#e11d48', '#ffe4ea'), 'life': ('#ea580c', '#ffedd5')}
ICON = {'ar': 'i_book', 'math': 'i_abacus', 'sci': 'i_brain', 'en': 'i_globe', 'life': 'i_heart'}
items = []
def mcq(q, opts, a): assert 0 <= a < len(opts); return ('mcq', q, opts, a)
def tf(q, a): return ('tf', q, bool(a))
def fill(q, a): assert '____' in q; return ('fill', q, str(a))
def short(q, a): return ('short', q, a)
def add(slug, kind, g, s, unit, lesson, title, desc, goals, concepts, expl, examples, points, qs, links=None, order=0):
    assert len(qs) >= 4 and points and desc
    items.append(dict(slug=slug, kind=kind, grade=g, subj=s, unit=unit, lesson=lesson, title=title, description=desc, goals=goals,
        concepts=[dict(t=a, d=b) for a, b in concepts], explanation=expl, examples=examples, points=points,
        questions=[dict(type=q[0], q=q[1], **({'opts': q[2], 'a': q[3]} if q[0] == 'mcq' else {'a': q[2]})) for q in qs], links=links or {}, sort=order or len(items) + 1))
def L(acts=(), lib=(), cards=None, quiz=None): return dict(acts=list(acts), lib=list(lib), cards=cards, quiz=quiz)

