def cmap(slug, g, s, unit, lesson, title, desc, branches, how, goals, points, src, order):
    by = {i['slug']: i for i in items}
    qs = by[src]['questions'][:5]
    items.append(dict(slug=slug, kind='concept_map', grade=g, subj=s, unit=unit, lesson=lesson, title=title, description=desc, goals=goals,
        concepts=[dict(t=a, d=b) for a, b in branches], explanation=how, examples=[], points=points, questions=qs, links=by[src]['links'], sort=order))
